class Solution {
public:
    int longestWPI(vector<int>& hours) {
        int n = hours.size();
        vector<int> P(n + 1, 0);
        for (int i = 0; i < n; i++) {
            P[i + 1] = P[i] + (hours[i] > 8 ? 1 : -1);
        }

        vector<int> stk;
        stk.push_back(0);
        for (int i = 1; i <= n; i++) {
            if (P[i] < P[stk.back()]) {
                stk.push_back(i);
            }
        }

        int ans = 0;
        for (int j = n; j >= 0; j--) {
            while (!stk.empty() && P[stk.back()] < P[j]) {
                ans = max(ans, j - stk.back());
                stk.pop_back();
            }
        }

        return ans;
    }
};
